algorithms.pseudocode:
enumerate_kw_witnesses(f, n):
  for x in {0,1}^n with f(x)=true:
    for y in {0,1}^n with f(y)=false:
      for i in 0..n-1:
        if x[i] != y[i]:
          yield (x, y, i)

analyze_incompressibility(elements, k):
  max_short = 2^(k+1) - 1
  if |elements| > max_short:
    return INCOMPRESSIBLE
  else:
    return COMPRESSIBLE
